import React from 'react';
import { BarChart2, Calendar, CheckSquare, MessageCircle, User } from 'react-feather';

const navigation = [
  { href: '#overview', label: 'Overview', Icon: BarChart2 },
  { href: '#balances', label: 'Leave balances', Icon: Calendar },
  { href: '#requests', label: 'My requests', Icon: CheckSquare },
  { href: '#profile', label: 'Profile', Icon: User },
];

const Sidebar = ({ isOpen, onClose, canApprove, onOpenChat }) => (
  <>
    <button className={`shell-backdrop ${isOpen ? 'visible' : ''}`} aria-label="Close navigation" onClick={onClose} />
    <aside className={`app-sidebar ${isOpen ? 'open' : ''}`} aria-label="Primary navigation">
      <div className="sidebar-brand">
        <img src="/okoa_float_logo.svg" alt="Okoa Float" />
        <span>Leave management</span>
      </div>
      <nav className="sidebar-nav">
        {navigation.map(({ href, label, Icon }, index) => (
          <a className={`sidebar-link ${index === 0 ? 'active' : ''}`} href={href} key={href} onClick={onClose}>
            <Icon size={18} aria-hidden="true" />
            <span>{label}</span>
          </a>
        ))}
        <button className="sidebar-link sidebar-button" onClick={() => { onOpenChat(); onClose(); }}>
          <MessageCircle size={18} aria-hidden="true" />
          <span>Chat</span>
        </button>
        {canApprove && <a className="sidebar-link" href="#approvals" onClick={onClose}><CheckSquare size={18} aria-hidden="true" /><span>Approvals</span></a>}
      </nav>
      <div className="sidebar-footer">Secure employee workspace</div>
    </aside>
  </>
);

export default Sidebar;
